const orders = items[0].json.list;


// -------------------
// SKU -> จำนวนซอง
// -------------------

const skuPackMap = {

"P514": 10,
"P514-1": 10,
"P514-2": 10,

"P515": 4,
"P515-2": 4,

"P516": 1,
"P516-1": 1,

"P516 - 2 ซอง": 2,

"P525": 20,

"P647": 5,

"P667": 3,

"P686": 2,

"P716": 11

};


// -------------------
// ตั้งค่าช่องทางที่ไม่ต้องการ
// -------------------

const excludeChannels = [

"รีวิว TIKTOK - นกฮูก"

];


// -------------------
// หา "เมื่อวาน"
// -------------------

const today = new Date();

const yesterday = new Date();

yesterday.setDate(today.getDate() - 1);

const targetDate =

yesterday.toISOString().split("T")[0];



// -------------------
// กรองเฉพาะ Order เมื่อวาน
// และตัด Order Voided
// -------------------

const yesterdayOrders = orders.filter(order => {

const orderDate =

new Date(order.orderdate)

.toISOString()

.split("T")[0];



const isVoided =

order.status?.toLowerCase() === "voided"

||

order.paymentstatus?.toLowerCase() === "voided";



return (

orderDate === targetDate

&&

!isVoided

);

});




// -------------------
// สรุปยอด
// -------------------

let totalOrders = 0;

let totalRevenue = 0;

let totalPacks = 0;

let aov = 0;

const channels = {};

const unknownSku = [];



for (const order of yesterdayOrders) {


const amount =

Number(order.amount || 0);



const channel =

order.saleschannel?.trim()

|| "Inbound";



if (

excludeChannels.includes(channel)

) {

continue;

}



if (

amount <= 0

) {

continue;

}



totalOrders++;

totalRevenue += amount;





// -------------------

// นับจำนวนซองจาก list

// -------------------

const products =

order.list || [];



for (

const product of products

) {


const sku =

product.sku?.trim()

|| "";



const qty =

Number(

product.number || 1

);



const packPerSku =

skuPackMap[sku];



if(packPerSku){

totalPacks +=

qty * packPerSku;

}

else if(sku){

unknownSku.push(sku);

}


}





// -------------------

// Revenue by Channel

// -------------------

if (

!channels[channel]

) {


channels[channel] = {

orders: 0,

revenue: 0

};


}



channels[channel].orders++;

channels[channel].revenue += amount;


}





// -------------------
// Average Order Value
// -------------------

aov =

totalOrders > 0

?

totalRevenue / totalOrders

:

0;




// -------------------
// เรียงยอดขายมาก -> น้อย
// -------------------

const sortedChannels =

Object.entries(channels)

.sort(

(a,b)=>

b[1].revenue - a[1].revenue

);




// -------------------
// เตรียมข้อมูล Flex
// -------------------

const flexChannels = [];



for (

const [channel,data]

of sortedChannels

){

flexChannels.push({

name:channel,

orders:data.orders,

revenue:data.revenue

});

}




// -------------------
// สร้างข้อความ LINE
// -------------------

let msg = "";



msg +=

"📊 รายงานยอดขายเมื่อวาน\n";


msg +=

`📅 ${targetDate}\n\n`;



msg +=

`🛒 Orders : ${

totalOrders.toLocaleString()

}\n`;



msg +=

`💰 Revenue : ${

totalRevenue.toLocaleString(

undefined,

{

minimumFractionDigits:2,

maximumFractionDigits:2

}

)

} บาท\n`;



msg +=

`📦 Total Packs : ${

totalPacks.toLocaleString()

} ซอง\n`;



msg +=

`💳 AOV : ${

aov.toLocaleString(

undefined,

{

minimumFractionDigits:2,

maximumFractionDigits:2

}

)

} บาท\n\n`;



msg +=

"📌 Revenue by Channel\n\n";





for (

const channel

of flexChannels

){


msg +=

`${channel.name}

• Orders : ${

channel.orders.toLocaleString()

}

• Revenue : ${

channel.revenue.toLocaleString(

undefined,

{

minimumFractionDigits:2,

maximumFractionDigits:2

}

)

} บาท


`;

}



if(

unknownSku.length

){

msg +=

`\n⚠️ SKU ไม่พบ Mapping\n${

[...new Set(

unknownSku

)]

.join(", ")

}`;

}




// -------------------
// Return Output
// -------------------

return [

{

json:{

date:targetDate,

orders:totalOrders,

revenue:totalRevenue,

aov,

totalPacks,

channels,

sortedChannels,

flexChannels,

unknownSku,

message:msg

}

}

];

