WITH active_cycle AS (SELECT id FROM budget_cycles WHERE is_active = TRUE ORDER BY start_date DESC LIMIT 1), spent AS (
 SELECT coalesce(category,'uncategorized') category, coalesce(sum(amount),0) spent FROM receipt_logs r JOIN active_cycle c ON r.budget_cycle_id=c.id WHERE coalesce(direction,'expense')='expense' GROUP BY coalesce(category,'uncategorized')
) SELECT t.category,t.target_amount,coalesce(s.spent,0) spent,(t.target_amount-coalesce(s.spent,0)) remaining FROM budget_category_targets t JOIN active_cycle c ON t.budget_cycle_id=c.id LEFT JOIN spent s ON s.category=t.category ORDER BY t.category;

