function cleanText(value) {
  return String(value ?? "")
    .replace(/\r/g, "")
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, "")
    .trim();
}

function normalizeLine(value) {
  return cleanText(value)
    .replace(/\s+/g, " ")
    .trim();
}

function getFilename() {
  try {
    const webhook = $("Python OCR Webhook").first();

    return (
      webhook.binary?.file?.fileName ||
      webhook.binary?.data?.fileName ||
      webhook.json?.body?.filename ||
      "document.pdf"
    );
  } catch {
    return "document.pdf";
  }
}

function findNextLine(lines, index, maxDistance = 3) {
  for (
    let next = index + 1;
    next < lines.length && next <= index + maxDistance;
    next++
  ) {
    const candidate = normalizeLine(lines[next]);

    if (candidate) {
      return candidate;
    }
  }

  return null;
}

function extractRecipientName(lines) {
  const triggerPattern =
    /(?:ให้ไว้เพื่?อแสดงว่า|ให้ไว้แก่|มอบให้แก่|this is to certify that|presented to|awarded to)/i;

  for (let index = 0; index < lines.length; index++) {
    if (triggerPattern.test(lines[index])) {
      return findNextLine(lines, index);
    }
  }

  // สำรอง: ค้นหาบรรทัดชื่อบุคคลภาษาไทย
  const thaiNamePattern =
    /^(?:(?:นาย|นาง|นางสาว|ดร\.?)\s*)?[ก-๙]{2,30}\s+[ก-๙]{2,40}$/;

  return lines.find((line) => thaiNamePattern.test(line)) || null;
}

function extractCourseTitle(lines) {
  const directPatterns = [
    /^(?:หลักสูตร|บทเรียน|รายวิชา|course|training|program)\s*[:：.-]?\s*(.+)$/i,
  ];

  for (const line of lines) {
    for (const pattern of directPatterns) {
      const match = line.match(pattern);

      if (match?.[1]) {
        return match[1].trim();
      }
    }
  }

  const triggerPattern =
    /(?:ได้ผ่านการอบรม|ผ่านการอบรม|สำเร็จการศึกษา|completed|completion of)/i;

  for (let index = 0; index < lines.length; index++) {
    if (triggerPattern.test(lines[index])) {
      const nextLine = findNextLine(lines, index);

      if (
        nextLine &&
        !/^(?:จำนวนชั่วโมง|โดยสถาบัน|วันที่|ให้ ณ วันที่)/i.test(nextLine)
      ) {
        return nextLine;
      }
    }
  }

  return null;
}

function extractIssueDate(lines, rawText) {
  const patterns = [
    /(?:ให้\s*ณ\s*วันที่|ออกให้\s*ณ\s*วันที่|วันที่)\s*[:：.-]?\s*(\d{1,2}\s+[ก-๙]+\s+\d{4})/i,

    /(?:date|issued|issue date)\s*[:：.-]?\s*(\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4})/i,

    /(?:date|issued|issue date)\s*[:：.-]?\s*(\d{4}-\d{2}-\d{2})/i,
  ];

  for (const pattern of patterns) {
    const match = rawText.match(pattern);

    if (match?.[1]) {
      return match[1].trim();
    }
  }

  return null;
}

function extractCertificateId(lines, rawText) {
  const labelledPatterns = [
    /(?:certificate\s*(?:id|no|number)|serial\s*no|ref(?:erence)?\s*no|เลขที่)\s*[:#：.-]?\s*([A-Za-z0-9/_-]{4,50})/i,
  ];

  for (const pattern of labelledPatterns) {
    const match = rawText.match(pattern);

    if (match?.[1]) {
      return match[1].trim();
    }
  }

  /*
   * ใบประกาศตัวอย่างมีรหัสสั้น เช่น 08f5e92
   * เลือกเฉพาะบรรทัดที่เป็นตัวอักษร/ตัวเลขเดี่ยว ๆ
   */
  const standaloneId = lines.find((line) =>
    /^[A-Fa-f0-9]{7,40}$/.test(line)
  );

  return standaloneId || null;
}

function extractLearningHours(lines, rawText) {
  const match = rawText.match(
    /จำนวนชั่วโมง(?:การเรียนรู้|การเรียนรู)?\s*[:：]?\s*(\d{1,3}(?::\d{2})?)\s*ชั่วโมง/i
  );

  return match?.[1] || null;
}

function extractOrganization(lines) {
  const preferredPatterns = [
    /^โดย(.+(?:สถาบัน|มหาวิทยาลัย|บริษัท|สำนักงาน|academy|university|institute|agency).*)$/i,
    /^(.*(?:สถาบันพัฒนาบุคลากรภาครัฐด้านดิจิทัล).*)$/i,
    /^(.*(?:สำนักงานพัฒนารัฐบาลดิจิทัล).*)$/i,
    /^(.*(?:Thailand Digital Government Academy).*)$/i,
  ];

  for (const pattern of preferredPatterns) {
    for (const line of lines) {
      const match = line.match(pattern);

      if (match) {
        return normalizeLine(match[1] || match[0])
          .replace(/^โดย\s*/, "")
          .trim();
      }
    }
  }

  return null;
}

function buildMarkdown(data) {
  return [
    "# รายงานผลการวิเคราะห์ใบประกาศนียบัตร",
    "",
    "## ข้อมูลสำคัญ",
    "",
    `- **ชื่อไฟล์:** ${data.filename}`,
    `- **ชื่อผู้รับ:** ${data.recipient_name || "-"}`,
    `- **หลักสูตร/บทเรียน:** ${data.course_title || "-"}`,
    `- **วันที่ออกเอกสาร:** ${data.issue_date || "-"}`,
    `- **รหัสใบประกาศ:** ${data.certificate_id || "-"}`,
    `- **จำนวนชั่วโมง:** ${data.learning_hours || "-"}`,
    `- **หน่วยงานผู้ออก:** ${data.issuing_organization || "-"}`,
    "",
    "## ข้อมูล OCR",
    "",
    `- **Engine:** ${data.ocr.engine || "-"}`,
    `- **OCR Version:** ${data.ocr.version || "-"}`,
    `- **ภาษา:** ${data.ocr.language || "-"}`,
    `- **จำนวนบรรทัด:** ${data.total_lines}`,
    "",
    "## ข้อความทั้งหมด",
    "",
    "```text",
    data.raw_ocr_text,
    "```",
  ].join("\n");
}

return $input.all().map((item) => {
  /*
   * HTTP Request อาจคืน object โดยตรง
   * หรือบางการตั้งค่าอาจครอบไว้ใน body
   */
  const ocr = item.json?.body ?? item.json ?? {};

  /*
   * ใช้ lines.text ก่อน เพราะเป็นข้อมูลที่จัดเป็นบรรทัดแล้ว
   * หากไม่มีจึง fallback ไป rawText
   */
  let lines = [];

  if (Array.isArray(ocr.lines)) {
    lines = ocr.lines
      .map((line) => {
        if (typeof line === "string") {
          return normalizeLine(line);
        }

        return normalizeLine(line?.text);
      })
      .filter(Boolean);
  }

  const rawText = cleanText(
    ocr.rawText ||
    ocr.text ||
    lines.join("\n")
  );

  if (lines.length === 0 && rawText) {
    lines = rawText
      .split("\n")
      .map(normalizeLine)
      .filter(Boolean);
  }

  if (!ocr.ok) {
    return {
      json: {
        success: false,
        error: {
          code: "OCR_FAILED",
          message:
            cleanText(ocr.error?.message || ocr.message || ocr.error) ||
            "PaddleOCR ไม่สามารถประมวลผลเอกสารได้",
        },
        ocr_response: ocr,
      },
    };
  }

  if (!rawText) {
    return {
      json: {
        success: false,
        error: {
          code: "OCR_EMPTY",
          message: "PaddleOCR ทำงานสำเร็จ แต่ไม่พบข้อความในเอกสาร",
        },
        ocr_response: ocr,
      },
    };
  }

  const filename = getFilename();

  const parsedData = {
    filename,
    recipient_name: extractRecipientName(lines),
    course_title: extractCourseTitle(lines),
    issue_date: extractIssueDate(lines, rawText),
    certificate_id: extractCertificateId(lines, rawText),
    learning_hours: extractLearningHours(lines, rawText),
    issuing_organization: extractOrganization(lines),
    total_lines: lines.length,
    raw_ocr_text: rawText,
    ocr: {
      engine: ocr.engine || null,
      version: ocr.ocrVersion || null,
      language: ocr.lang || ocr.requestedLang || null,
    },
  };

  const markdownContent = buildMarkdown(parsedData);

  return {
    json: {
      success: true,
      filename,
      data: {
        json_payload: parsedData,
        text_content: rawText,
        markdown_content: markdownContent,
      },
    },
  };
});

