function clean(value) {
  return String(value ?? '-')
    .replace(/\r/g, '')
    .replace(/[{}]/g, '')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
    .trim() || '-';
}

function telegramPlain(value) {
  return clean(value)
    .replace(/[*_`[\]()~>#+=|\\]/g, ' ')
    .replace(/-{2,}/g, '-')
    .replace(/[ \t]+/g, ' ');
}

